/** The sheet's today when the claim was deferred; null for one never deferred, or before that was kept. */
@Column(name = "deferred_on")
private LocalDate deferredOn;

/** The last sheet's today a reminder was written for the claim; null for one never reminded. */
@Column(name = "reminded_on")
private LocalDate remindedOn;

/** Whether the claim was added while its period was soft-closed. */
@Column(name = "late_entry", nullable = false)

public void setTerms(int terms) {
    this.terms = terms;
}

public LocalDate getRemindedOn() {
    return remindedOn;
}

public void setRemindedOn(LocalDate remindedOn) {
    this.remindedOn = remindedOn;
}

public LocalDate getDeferredUntil() {
    return deferredUntil;
}
private void copyClaims(String sheetId, String toSheetId, Map<Long, Long> people) {
    List<Claim> originals = new ArrayList<>(claims.findBySheetIdOrderByListedDescIdDesc(sheetId));
    originals.sort(Comparator.comparing(Claim::getListed).thenComparing(Claim::getId));
    Map<Long, Long> copies = new LinkedHashMap<>();
    for (Long person : people.keySet()) {
        for (Claim c : originals) {
            if (!c.getPersonId().equals(person)) {
                continue;
            }
            Long copy = insert("INSERT INTO claim (sheet_id, person_id, amount, claim_date, note, status,"
                    + " settled_due, opened_by, edited_by, corrects, split_from, rounds_on, due_by, terms,"
                    + " deferred_until, deferred_on, reminded_on, late_entry, proofs, ref, tags, void_reason,"
                    + " added_mark) SELECT ?, ?, amount, claim_date, note, status, settled_due, opened_by,"
                    + " edited_by, corrects, split_from, rounds_on, due_by, terms, deferred_until, deferred_on,"
                    + " reminded_on, late_entry, proofs, ref, tags, void_reason, added_mark FROM claim WHERE id = ?", toSheetId,
                    people.get(person), c.getId());
            copies.put(c.getId(), copy);
            jdbc.update("INSERT INTO claim_log (claim_id, status, by_user, on_date, due) SELECT ?, status,"
                    + " by_user, on_date, due FROM claim_log WHERE claim_id = ? ORDER BY id", copy, c.getId());
            jdbc.update("INSERT INTO claim_comment (claim_id, by_user, on_date, text) SELECT ?, by_user,"
                    + " on_date, text FROM claim_comment WHERE claim_id = ? ORDER BY id", copy, c.getId());
            jdbc.update("INSERT INTO claim_line (claim_id, label, qty, unit) SELECT ?, label, qty, unit"
                    + " FROM claim_line WHERE claim_id = ? ORDER BY id", copy, c.getId());
        }
    }

    return saved;
}

/**
 * Writes a reminder for an OPEN or PENDING claim, which shows the sheet's today as its reminded date. Refused for
 * a claim in any other status and one already reminded on the sheet's today; a reminder changes none of the
 * claim's figures, so one whose due-by falls in a closed period may still be reminded.
 */
@Transactional
public Claim remind(String by, String sheetId, Long id) {
    sheets.lock(sheetId);
    Claim claim = claims.findWithLockByIdAndSheetId(id, sheetId)
            .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
    if (!claim.getStatus().isOpen()) {
        throw new ResponseStatusException(HttpStatus.CONFLICT,
                "A " + claim.getStatus() + " claim cannot be reminded.");
    }
    LocalDate today = sheets.load(sheetId).getToday();
    if (today != null && today.equals(claim.getRemindedOn())) {
        throw new ResponseStatusException(HttpStatus.CONFLICT, "The claim was already reminded today.");
    }
    claim.setRemindedOn(today);
    Claim saved = claims.saveAndFlush(claim);
    audit.recordOnCommit(record("REMIND", by, person(sheetId, saved.getPersonId()), saved));
    return saved;
}

